camera.position.set(0.36, 3.44, 16.67);
camera.lookAt(0.36, 3.44, 0);
camera.name = 'ref';

// ---------- keyframes ----------
const PERIOD = 5540;
const KT = [0, 800, 1530, 2330, 3130, 3930, 4670, 5470, 5540];
const SQT = [1.1, 0.92, 1.1];
const HSQ = [0.7, 0.68, 0.7, 0.45];
